    execucao: Execucao = Field(default_factory=Execucao)
    bens: list[BemPenhorado] = Field(default_factory=list)
    recursos: str | None = None
    observacoes_leilao: list[str] = Field(default_factory=list)


class Etapa(BaseModel):
class LeilaoCreate(BaseModel):
    processo_id: UUID
    primeiro_leilao_data: date | None = None


class SugestaoOut(BaseModel):
    primeiro_leilao_em: datetime
    segundo_leilao_em: datetime


class BloqueioOut(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: UUID
    data: date
    motivo: str


class BloqueioCreate(BaseModel):
    data: date
    motivo: str = Field(min_length=1, max_length=200)


class FeriadoOut(BaseModel):
    data: date
    motivo: str

class EditalOut(BaseModel):
    id: UUID
    leilao_id: UUID
    processo_id: UUID
    conteudo_markdown: str
    criado_em: datetime
    atualizado_em: datetime | None


